function rank(id){return ranks[id]||0}
function dashCooldown(){return 2-rank('stride')*.18}
function lureCooldown(){return 7-rank('lure')*.6}
function resetGrowth(){playerLevel=1;xp=0;xpNeed=6;pendingUpgrades=0;upgradeChoices=[];ranks={};maxHearts=3;litOrder=[];threads=[];waveBanner=0;runStartStage=level;$('upgrade-panel').classList.add('hidden');updateBuild()}
function gainXP(amount){xp+=amount;while(xp>=xpNeed){xp-=xpNeed;playerLevel++;pendingUpgrades++;xpNeed=6+(playerLevel-1)*3}}
function offerUpgrade(){if(!pendingUpgrades||state!=='playing')return;state='upgrade';keys={};let pool=upgradePool.filter(u=>rank(u.id)<u.max&&(!u.requires||rank(u.requires)));if(pool.length<3)pool=pool.concat([{id:'blessing',icon:'✧',name:'끝없는 달빛',tag:'한계 돌파',desc:'모든 공격 피해 +0.5',max:Infinity},{id:'mend',icon:'♡',name:'새벽의 위로',tag:'회복',desc:'체력 모두 회복 · 남은 시간 +20초',max:Infinity},{id:'reserve',icon:'↻',name:'다시 반짝',tag:'재정비',desc:'대시·유령화 즉시 회복 · 폭발 완충',max:Infinity}]);upgradeChoices=pool.map(u=>({u,n:Math.random()})).sort((a,b)=>a.n-b.n).slice(0,3).map(o=>o.u);$('upgrade-title').textContent='모찌 LV.'+(playerLevel-pendingUpgrades+1);$('upgrade-sub').textContent='성장 하나를 골라 줘 · 모찌에게 어울리는 선물을 골라 줘';$('upgrade-cards').innerHTML=upgradeChoices.map((u,i)=>'<button class="upgrade-card" id="pick-'+i+'"><span class="card-top"><b>'+u.tag+'</b><kbd>'+(i+1)+'</kbd></span><span class="card-icon">'+u.icon+'</span><strong>'+u.name+'</strong><span class="card-desc">'+u.desc+'</span><small>'+(u.max===Infinity?'반복 선택 가능':(rank(u.id)+1)+' / '+u.max+' 강화')+'</small></button>').join('');upgradeChoices.forEach((u,i)=>$('pick-'+i).onclick=()=>chooseUpgrade(i));$('upgrade-panel').classList.remove('hidden');$('pick-0').focus()}
function chooseUpgrade(i){if(state!=='upgrade'||!upgradeChoices[i])return;let u=upgradeChoices[i];ranks[u.id]=rank(u.id)+1;if(u.id==='heart'){maxHearts++;hearts=Math.min(maxHearts,hearts+2)}if(u.id==='mend'){hearts=maxHearts;time+=20}if(u.id==='reserve'){cool=0;lureCool=0;energy=3}if(u.id==='unlock_thread')rebuildThreads();if(u.id==='unlock_nova')energy=3;pendingUpgrades--;upgradeChoices=[];$('upgrade-panel').classList.add('hidden');keys={};state='playing';updateBuild();sfx('choose');say('✦ '+u.name+' 획득! 새로운 달빛이 함께해.');canvas.focus();if(pendingUpgrades)offerUpgrade()}
function updateBuild(){$('build').textContent=Object.entries(ranks).map(([id,n])=>(upgradePool.find(u=>u.id===id)?.name|| (id==='blessing'?'끝없는 달빛':id==='reserve'?'다시 반짝':'새벽의 위로'))+' '+n).join(' · ')||'아직 강화가 없어. 귀신을 쓰러뜨려 경험치를 모아 줘.'}
function end(){if(state!=='playing')return;state='lost';keys={};$('overlay').innerHTML='<div class="badge">NIGHT '+level+' · 모험 기록</div><h2>오늘도 멀리 왔어.<br><em>다음 밤에 다시 만나.</em></h2><p>모찌 LV.'+playerLevel+' · 귀신 '+kills+'마리 퇴치<br>별빛 점수 '+score.toLocaleString()+' · 최고 '+bestScore.toLocaleString()+'<br>난이도 '+runStartStage+' → '+level+' · 강화 '+Object.values(ranks).reduce((a,b)=>a+b,0)+'개</p><button class="primary" id="again">1단계부터 새 모험 →</button><small>새 모험에서는 캐릭터 성장과 강화를 새로 시작해.</small>';$('overlay').classList.remove('hidden');$('again').onclick=()=>{level=1;start()};sfx('hurt')}
function deliver(){if(state!=='playing')return;let index=houses.findIndex(h=>!h.lit&&Math.hypot(player.x-h.x,player.y-h.y-30)<85);if(index<0){say('불이 꺼진 집 앞에서 E를 눌러 줘.');return}if(bag<3){say('별사탕 '+(3-bag)+'개가 더 필요해!');return}let h=houses[index];h.lit=true;bag=0;done++;hearts=Math.min(maxHearts,hearts+1);addScore(300);if(rank('unlock_thread')&&litOrder.length){let prev=houses[litOrder[litOrder.length-1]];threads.push({a:{x:prev.x,y:prev.y+45},b:{x:h.x,y:h.y+45},cool:0,flash:0})}litOrder.push(index);burst(h.x,h.y,'#ffdf9a',35);sfx('delivery');say(done>=2&&rank('unlock_thread')?'⌁ 등불의 실이 연결됐어! 실을 대시로 가로질러 연쇄 공격.':letters[index]);if(done===5){if(level%5===0)spawnBoss();else nextWave()}}
function nextWave(){addScore(800+Math.floor(time*2));threads.forEach(t=>pulseThread(t));level++;relocateHouses();setupBiome();stars=[];for(let i=0;i<60;i++)spawnStar();unlocked=Math.max(unlocked,level);try{localStorage.setItem('mochi-stage',String(unlocked))}catch{}houses.forEach(h=>h.lit=false);done=0;litOrder=[];threads=[];time=difficulty().seconds;waveBanner=4;inv=Math.max(inv,2);energy=3;ghosts.forEach((g,i)=>{if(g.dead)return;let stats=ghostStats(i),ratio=g.hp/g.maxHp;g.maxHp=stats.maxHp;g.hp=Math.max(1,Math.ceil(g.maxHp*ratio));g.elite=stats.elite});while(ghosts.length<difficulty().count){let i=ghosts.length;ghosts.push({...freePoint(500),p:i*2,...ghostStats(i)})}say('☾ 난이도 '+level+'! 등불은 다시 잠들었어. 집들이 이사했어! '+biome().name+' · '+biome().hint);sfx('wave')}
function projection(p,a,b){let dx=b.x-a.x,dy=b.y-a.y,len=dx*dx+dy*dy,t=len?Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/len)):0;return {x:a.x+dx*t,y:a.y+dy*t}}
function crossed(a,b,c,d){let cross=(p,q,r)=>(q.x-p.x)*(r.y-p.y)-(q.y-p.y)*(r.x-p.x);let s1=cross(c,d,a),s2=cross(c,d,b);if(s1*s2>0||Math.abs(s1-s2)<1e-6)return false;return cross(a,b,c)*cross(a,b,d)<=0}
function checkThreads(previous){if(dash<=0)return;threads.forEach(t=>{if(t.cool<=0&&crossed(previous,player,t.a,t.b))pulseThread(t)})}
function pulseThread(t){if(!rank('unlock_thread'))return;t.cool=Math.max(2,6-rank('thread')*.6);t.flash=.7;ghosts.forEach(g=>{if(g.dead)return;let p=projection(g,t.a,t.b);if(Math.hypot(g.x-p.x,g.y-p.y)<120&&clearLine(p,g)){hitGhost(g,4+rank('thread')*2+rank('blessing')*.5,45);addScore(30)}});energy=Math.min(3,energy+1);floaters.push({x:player.x,y:player.y-45,label:'등불 실뜨기!',color:'#98fff0',life:1.3});sfx('thread');shake=5}
function drawThreads(){threads.forEach(t=>{ctx.save();ctx.shadowColor='#9cfff0';ctx.shadowBlur=t.flash>0?25:8;if(t.flash>0){line(t.a.x,t.a.y,t.b.x,t.b.y,'#a6ffe51c',240)}line(t.a.x,t.a.y,t.b.x,t.b.y,t.flash>0?'#e5fff8':t.cool>0?'#7caaa444':'#9cffe58c',t.flash>0?18:2);let mid={x:(t.a.x+t.b.x)/2,y:(t.a.y+t.b.y)/2};star(mid.x,mid.y,t.flash>0?14:8,t.cool>0?'#78a99c':'#c8ffee');ctx.restore()})}
function updateHUD(){$('score').textContent=score.toLocaleString();$('best-score').textContent=bestScore.toLocaleString();$('biome').textContent=biome().name;$('biome').title=biome().hint;let fmt=v=>v>0?v.toFixed(1)+'s':'준비';$('stage').textContent='NIGHT '+level;$('player-level').textContent='LV.'+playerLevel;$('xp-label').textContent=xp+' / '+xpNeed;$('xp-fill').style.width=Math.min(100,xp/xpNeed*100)+'%';$('xpbar').setAttribute('aria-valuenow',xp);$('xpbar').setAttribute('aria-valuemax',xpNeed);$('time').textContent=String(Math.floor(time/60)).padStart(2,'0')+':'+String(Math.floor(time%60)).padStart(2,'0');$('bag').textContent=bag+'/3';$('delivered').textContent=done+'/'+houses.length;$('hearts').textContent=heartSymbols();$('kill-count').textContent=kills;$('j-status').textContent=fmt(attackCool);$('k-status').textContent=energy===3?'준비':energy+'/3';$('q-status').textContent=fmt(lureCool);$('dash-status').textContent=fmt(cool);$('thread-status').textContent=threads.length?'빛의 실 '+threads.length+'개 · 대시로 가로지르기':'첫 배달부터 달의 실패와 집이 실로 연결돼';$('weather').textContent=level>=4?(elapsed%14>=10?'돌풍 '+wind().label:elapsed%14>=8?'돌풍 예고 '+wind().label:'고요한 숲'):'고요한 숲';if(waveBanner>0){ctx.fillStyle='#142c36d9';ctx.fillRect(300,135,500,76);text('☾ NIGHT '+level+' · 더 깊어진 밤',550,166,24,'#ffe0a0');text(biome().name+' · 새로운 집에서 기다리는 친구들',550,193,13,'#c1ded2')}}

