let score=0,bestScore=0,patches=[],haste=0,waveClock=0,musicEnabled=true,musicVolume=.45,musicBus=null,nextBeat=0,beatIndex=0,musicTheme=-1;
try{bestScore=Math.max(0,Number(localStorage.getItem('mochi-survival-best'))||0)}catch{}
function biome(){return biomes[Math.floor((level-1)/3)%biomes.length]}
function biomeIndex(){return Math.floor((level-1)/3)%biomes.length}
function addScore(n){score+=Math.max(0,Math.round(n));if(score>bestScore){bestScore=score;try{localStorage.setItem('mochi-survival-best',String(bestScore))}catch{}}}
function relocateHouses(){let used=[];let seed=(level*7417+19)>>>0;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}const regions=[{x:120,y:130,w:480,h:390},{x:760,y:120,w:620,h:390},{x:1590,y:120,w:470,h:390},{x:120,y:900,w:640,h:320},{x:1450,y:910,w:610,h:310}];houses.forEach((h,i)=>{let region=regions[i],candidates=[];for(let x=region.x;x<region.x+region.w;x+=40)for(let y=region.y;y<region.y+region.h;y+=40)if(!blocked(x,y,85)&&!blocked(x,y+55,30)&&used.every(p=>Math.hypot(p.x-x,p.y-y)>240)&&Math.hypot(h.x-x,h.y-y)>170)candidates.push({x,y});if(!candidates.length)throw Error('No safe house location');let p=candidates[Math.floor(rand()*candidates.length)];Object.assign(h,p,{lit:false});used.push(p)})}
function setupBiome(){patches=[{x:700,y:620},{x:1510,y:830},{x:260,y:760},{x:980,y:1110},{x:1960,y:700}].map(p=>({...p,r:biomeIndex()===1?90:32,cool:0}));haste=0;waveClock=0;musicTheme=-1}
function inFrost(x,y){return biomeIndex()===1&&patches.some(p=>Math.hypot(x-p.x,y-p.y)<p.r)}
function tickTerrain(dt){haste=Math.max(0,haste-dt);waveClock+=dt;patches.forEach(p=>{p.cool=Math.max(0,p.cool-dt);if(biomeIndex()===0&&p.cool<=0&&Math.hypot(player.x-p.x,player.y-p.y)<38){p.cool=9;haste=3;cool=0;burst(p.x,p.y,'#b4ffd2',22);sfx('spring');say('↗ 바람버섯! 3초 가속 · 대시 즉시 회복')}})}
function drawTerrain(){const b=biome();patches.forEach((p,i)=>{if(biomeIndex()===0){ellipse(p.x,p.y+12,24,9,'#102c3380');ctx.fillStyle='#d1d7b5';ctx.fillRect(p.x-5,p.y-5,10,20);ellipse(p.x,p.y-6,27,15,p.cool>0?'#658c7d':'#b0e9a5');ellipse(p.x-8,p.y-10,4,3,'#eef3c9');ellipse(p.x+11,p.y-5,5,3,'#eef3c9');if(p.cool<=0)glow(p.x,p.y,50,'#a5ffbb28')}else if(biomeIndex()===1){ellipse(p.x,p.y,p.r,p.r,'#a4e4fc25');ctx.strokeStyle='#c1efff60';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.stroke();for(let j=0;j<6;j++){let a=j*Math.PI/3;line(p.x,p.y,p.x+Math.cos(a)*55,p.y+Math.sin(a)*55,'#c9efff60',2)}}else{star(p.x,p.y,25,'#ceb7ef4d');glow(p.x,p.y,55,'#eab8ff18')}});for(let i=0;i<55;i++){let x=(i*173.77+Math.sin(elapsed*.4+i)*18)%WORLD.w,y=(i*97.13+elapsed*(biomeIndex()===1?9:2))%WORLD.h;ellipse(x,y,biomeIndex()===1?2:1.5,biomeIndex()===1?2:1.5,b.accent+'60')}}
function musicNote(freq,dur,when,volume,type='sine'){let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,when);g.gain.setValueAtTime(.0001,when);g.gain.exponentialRampToValueAtTime(volume,when+.035);g.gain.exponentialRampToValueAtTime(.0001,when+dur);o.connect(g);g.connect(musicBus);o.start(when);o.stop(when+dur+.01)}
function tickMusic(){if(!audio)return;try{if(!musicBus){musicBus=audio.createGain();musicBus.connect(audio.destination)}let live=['playing','upgrade','levelup','cinematic'].includes(state),volume=musicEnabled&&!muted&&live?musicVolume*(state==='upgrade'?.4:1):0;musicBus.gain.setTargetAtTime(volume,audio.currentTime,.08);if(!volume){nextBeat=audio.currentTime;return}if(audio.state==='suspended')return;let theme=bossActive?3:biomeIndex();if(musicTheme!==theme){musicTheme=theme;nextBeat=audio.currentTime+.03;beatIndex=0}if(nextBeat<audio.currentTime-.5)nextBeat=audio.currentTime;let b=bossActive?{notes:[57,60,64,63,69,72],base:33}:biome(),step=[.31,.34,.28,.19][theme],midi=n=>440*Math.pow(2,(n-69)/12),pattern=[0,2,4,2,1,3,5,3,0,2,3,1,4,3,2,1];while(nextBeat<audio.currentTime+.12){let p=beatIndex%16,chord=[0,-5,-3,-7][Math.floor(beatIndex/16)%4];musicNote(midi(b.notes[pattern[p]]+chord),step*1.8,nextBeat,.035,'sine');if(bossActive)musicNote(midi(b.base+(beatIndex%2?7:0)),step*.8,nextBeat,.04,'triangle');if(beatIndex%4===0)musicNote(midi(b.base+chord-12),step*3.5,nextBeat,.05,'triangle');if(beatIndex%16===0)[0,7,12].forEach(n=>musicNote(midi(b.base+chord+n),step*14,nextBeat,.012,'sine'));nextBeat+=step;beatIndex++}}catch{}}
function toggleMusic(){musicEnabled=!musicEnabled;$('music-toggle').textContent=musicEnabled?'♪ BGM 켜짐':'♪ BGM 꺼짐';$('music-toggle').setAttribute('aria-pressed',String(musicEnabled));if(musicEnabled&&!audio)sfx('start');tickMusic()}
$('music-toggle').onclick=toggleMusic;$('music-volume').oninput=e=>{musicVolume=Number(e.target.value)/100;tickMusic()};$('view-toggle').onclick=()=>{let active=document.body.classList.toggle('playing-view');$('view-toggle').textContent=active?'설명 보기':'게임 크게';canvas.focus()};

