function rebuildThreads(){threads=[];for(let i=1;i<litOrder.length;i++){let a=houses[litOrder[i-1]],b=houses[litOrder[i]];threads.push({a:{x:a.x,y:a.y+45},b:{x:b.x,y:b.y+45},cool:0,flash:0})}}
// Separated cells keep wide corridors connected; random arms create I/L/T shapes.
function randomizeWalls(){walls.length=0;for(let row=0;row<3;row++)for(let col=0;col<5;col++){if(row===1&&col===2)continue;if(Math.random()<.15)continue;let x=160+col*400+Math.random()*50,y=190+row*410+Math.random()*40,len=110+Math.random()*95,thick=35+Math.random()*25,vertical=Math.random()<.5;walls.push({x,y,w:vertical?thick:len,h:vertical?len:thick});if(Math.random()<.65)walls.push({x,y,w:vertical?len:thick,h:vertical?thick:len});if(Math.random()<.25)walls.push({x:x+(vertical?0:len-thick),y:y+(vertical?len-thick:0),w:vertical?len:thick,h:vertical?thick:len})}}
