function tickBoss(g,dt){if(g.dead)return;g.flash=Math.max(0,g.flash-dt);g.spawnShield=Math.max(0,g.spawnShield-dt);if(g.spawnShield>0)return;let dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;g.timer-=dt;if(g.mode==='warn'){if(g.timer<=0){for(let i=0;i<18;i++){let a=i*Math.PI/9+elapsed*.2;shots.push({x:g.x,y:g.y,vx:Math.cos(a)*240,vy:Math.sin(a)*240,life:4})}effects.push({type:'boss',x:g.x,y:g.y,range:190,life:.7,max:.7,color:'#efa4ff'});if(d<190&&clearLine(g,player))hurt(2);g.mode='walk';g.timer=2.8;sfx('slam')}}else{moveBody(g,dx/d*(90+level*2)*dt,dy/d*(90+level*2)*dt,g.r);if(g.timer<=0){g.mode='warn';g.timer=1.15;sfx('lure')}}if(d<g.r+17)hurt(2)}
