let stickPointer=null;
const stick=$('touch-stick'),stickKnob=$('stick-knob');
function releaseStick(){stickPointer=null;keys.w=keys.a=keys.s=keys.d=false;stickKnob.style.transform='translate(-50%,-50%)'}
function moveStick(e){let rect=stick.getBoundingClientRect(),dx=e.clientX-rect.left-rect.width/2,dy=e.clientY-rect.top-rect.height/2,d=Math.hypot(dx,dy),limit=rect.width*.3,scale=d>limit?limit/d:1;stickKnob.style.transform='translate(calc(-50% + '+dx*scale+'px),calc(-50% + '+dy*scale+'px))';keys.a=dx< -10;keys.d=dx>10;keys.w=dy< -10;keys.s=dy>10}
stick.onpointerdown=e=>{if(state!=='playing'||stickPointer!==null)return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)};
stick.onpointermove=e=>{if(e.pointerId===stickPointer){e.preventDefault();moveStick(e)}};
stick.onpointerup=stick.onpointercancel=stick.onlostpointercapture=e=>{if(e.pointerId===stickPointer)releaseStick()};
