function sizeVillage(){const count=Math.min(10,3+bossWins);while(houses.length>count)houses.pop();while(houses.length<count)houses.push({x:0,y:0,name:houseNames[houses.length],color:['#b68f79','#b09caf','#93aaa1'][houses.length%3]})}
relocateHouses=function(){let candidates=[];for(let y=140;y<1280;y+=70)for(let x=120;x<2100;x+=70)if(!blocked(x,y,88)&&!blocked(x,y+50,30)&&Math.hypot(x-1050,y-720)>230)candidates.push({x,y});let used=[];houses.forEach(h=>{let viable=candidates.filter(p=>used.every(q=>Math.hypot(q.x-p.x,q.y-p.y)>260)&&Math.hypot(h.x-p.x,h.y-p.y)>180);if(!viable.length)viable=candidates.filter(p=>used.every(q=>Math.hypot(q.x-p.x,q.y-p.y)>200));if(!viable.length)throw Error('Village placement exhausted');let p=viable[Math.floor(Math.random()*viable.length)];Object.assign(h,p,{lit:false});used.push(p)})};
difficulty=function(n=level){return {seconds:(simpleMode?300:245)+Math.min(60,bossWins*10),speed:(simpleMode?63:78)+Math.min(simpleMode?48:60,(n-1)*2.4),count:Math.min(simpleMode?23:30,(simpleMode?5:7)+Math.floor((n-1)*(simpleMode?.65:.85))),range:850}};
