nextWave=function(){if(bossActive)return;let fast=Math.max(0,Math.round(18*(1-waveClock/100)));gainXP(15+level*3+fast);addScore(800+fast*30+Math.floor(time*2));level++;bossCleared=false;stageKills=0;echoes=[];sizeVillage();randomizeWalls();relocateHouses();setupBiome();player.x=1050;player.y=720;shots=[];stars=[];for(let i=0;i<65;i++)spawnStar();done=bag=0;litOrder=[];threads=[];time=difficulty().seconds;waveBanner=2.5;inv=2;energy=3;ghosts=Array.from({length:difficulty().count},(_,i)=>({...freePoint(430),p:i*2,...ghostStats(i)}));say('NIGHT '+level+' · 진입 EXP +'+(15+(level-1)*3+fast)+(fast?' · 빠른 배달 보너스 +'+fast:'')+(level%10===0?' · 배달 완료 후 유령의 왕 등장!':''));sfx('wave')};
