pulseThread=function(t,scale=1,echo=false){if(scene||!rank('unlock_thread'))return;if(!echo)t.cool=Math.max(2.5,5-rank('thread')*.4);if(echo)t.echoFlash=.65;else t.flash=.65;let hits=0;ghosts.forEach(g=>{if(g.dead)return;let p=projection(g,t.a,t.b);if(Math.hypot(g.x-p.x,g.y-p.y)<threadWidth()&&clearLine(p,g)){hitGhost(g,(6+rank('thread')*1.5+rank('blessing')*.5)*scale,echo?12:40,echo?'echo':'thread');if(rank('frost_knot'))g.threadSlow=1+rank('frost_knot')*.6;hits++}});if(!echo){energy=Math.min(3,energy+1);if(hits&&rank('shuttle'))cool=Math.max(.45,cool-.15*rank('shuttle'));addScore(hits*20);if(rank('moon_refrain'))echoes.push({t,delay:.45,scale:.25})}floaters.push({x:player.x,y:player.y-45,label:echo?'⌁ 메아리':'⌁ 달빛 실뜨기!',color:echo?echoColor():'#98fff0',life:.9});sfx('thread');shake=echo?2:4};
checkThreads=function(previous){if(dash<=0)return;if(threadDashId!==dashSerial){threadDashId=dashSerial;dashThreads.clear();comboEchoed=false}threads.forEach(t=>{if(t.cool<=0&&!dashThreads.has(t)&&crossed(previous,player,t.a,t.b)){dashThreads.add(t);pulseThread(t)}});if(dashThreads.size>=2&&!comboEchoed){comboEchoed=true;Array.from(dashThreads).slice(0,3).forEach(t=>echoes.push({t,delay:.3,scale:rank('double_weave')?.65:.4}));inv=Math.max(inv,rank('silk_guard')?.7:inv);say('겹실뜨기! 한 대시로 여러 실을 갈랐어 · 작은 메아리 발동');sfx('perfect')}};
drawThreads=function(){if(litOrder.length){glow(moonSpool.x,moonSpool.y,48,'#dbc7ff44');star(moonSpool.x,moonSpool.y,17,'#e1ccff');text('달의 실패',moonSpool.x,moonSpool.y+35,11,'#e8d9ff')}threads.forEach(t=>{ctx.save();ctx.shadowColor='#9cfff0';ctx.shadowBlur=t.flash>0?25:8;if(t.flash>0)line(t.a.x,t.a.y,t.b.x,t.b.y,'#a6ffe526',threadWidth()*2);line(t.a.x,t.a.y,t.b.x,t.b.y,t.flash>0?'#e5fff8':t.cool>0?'#7caaa455':'#9cffe5bb',t.flash>0?15:3);let mid={x:(t.a.x+t.b.x)/2,y:(t.a.y+t.b.y)/2};star(mid.x,mid.y,t.flash>0?15:9,t.cool>0?'#78a99c':'#edffe7');if(t.cool<=0)text('대시 ↯',mid.x,mid.y-18,11,'#d2ffe8');ctx.restore()})};
