moonBolt=function(){if(state!=='playing'||!rank('unlock_bolt')||boltCool>0)return;let target=mothTarget(player);if(!target){say('가까이 보이는 유령을 찾으면 별나방이 날아가!');return}boltCool=4;let a=Math.atan2(target.y-player.y,target.x-player.x);[-.4,.4].forEach(off=>shots.push({x:player.x,y:player.y,vx:Math.cos(a+off)*340,vy:Math.sin(a+off)*340,life:2.6,friendly:true,moth:true,target,damage:3+rank('bolt')*.7}));sfx('lure')};
