offerUpgrade=function(){if(state!=='playing'||(!pendingUpgrades&&!bossRewards))return;state='upgrade';keys={};specialChoice=bossRewards>0;let pool=(specialChoice?relics:upgradePool).filter(u=>rank(u.id)<u.max&&(!u.requires||rank(u.requires))&&u.id!=='unlock_thread'&&!(simpleMode&&u.id==='auto_delivery'));if(pool.length<3)pool=pool.concat([{id:'mend',icon:'♡',name:'새벽의 위로',tag:'회복',desc:'체력 모두 회복 · 시간 +20초',max:Infinity},{id:'reserve',icon:'↻',name:'다시 반짝',tag:'재정비',desc:'대시·유령화 즉시 회복 · 폭발 완충',max:Infinity},{id:'blessing',icon:'✧',name:'더 깊은 달빛',tag:'성장',desc:'실뜨기·폭발 피해 +0.5 · J 피해 +0.15',max:Infinity}].filter(u=>!pool.some(p=>p.id===u.id)));pool=pool.map(u=>({u,n:Math.random()})).sort((a,b)=>a.n-b.n).map(o=>o.u);upgradeChoices=pool.slice(0,3);if(!specialChoice){let weave=pool.find(u=>['thread','weave_wide','frost_knot','shuttle'].includes(u.id));if(weave&&!upgradeChoices.includes(weave))upgradeChoices[2]=weave}$('upgrade-title').textContent=specialChoice?'밤을 되찾은 선물 · 특별 강화':'모찌 LV.'+(playerLevel-pendingUpgrades+1);$('upgrade-sub').textContent=specialChoice?'밤을 되찾은 보상 · 하나를 골라 다음 마을로':'퇴치 · 배달 · 다음 밤 진입으로 성장해';$('upgrade-cards').innerHTML=upgradeChoices.map((u,i)=>'<button class="upgrade-card" id="pick-'+i+'"><span class="card-top"><b>'+u.tag+'</b><kbd>'+(i+1)+'</kbd></span><span class="card-icon">'+u.icon+'</span><strong>'+u.name+'</strong><span class="card-desc">'+u.desc+'</span><small>'+(u.max===Infinity?'반복 선택 가능':(rank(u.id)+1)+' / '+u.max+' 강화')+'</small></button>').join('');upgradeChoices.forEach((u,i)=>$('pick-'+i).onclick=()=>chooseUpgrade(i));$('upgrade-panel').classList.remove('hidden');$('pick-0').focus()};
const regularChoose=chooseUpgrade;chooseUpgrade=function(i){if(state!=='upgrade'||!upgradeChoices[i])return;let wasSpecial=specialChoice;if(wasSpecial){bossRewards--;pendingUpgrades++}specialChoice=false;inv=Math.max(inv,1);regularChoose(i);if(state==='playing'&&bossRewards)offerUpgrade()};
