spawnBoss=function(){if(bossActive)return;bossActive=true;let hp=Math.round((70+level*5)*(simpleMode?.7:1));ghosts.push({type:'boss',x:1100,y:700,r:58,hp,maxHp:hp,dead:false,flash:0,stun:0,timer:3,mode:'walk',spawnShield:2,path:[],repath:0});ghosts.filter(g=>g.type!=='boss'&&!g.dead).forEach((g,i)=>{if(i%2){g.dead=true;g.respawn=14}});inv=Math.max(inv,2);musicTheme=-1;say('유령의 왕 등장! 실을 엮어 쓰러뜨리자 · 특별 강화와 다음 집이 기다려');sfx('nova')};
function bodyLine(a,b,r){let n=Math.ceil(Math.hypot(b.x-a.x,b.y-a.y)/12);for(let i=0;i<=n;i++)if(blocked(a.x+(b.x-a.x)*i/Math.max(1,n),a.y+(b.y-a.y)*i/Math.max(1,n),r))return false;return true}
// Radius-aware grid BFS; never cuts blocked corners or walks through a wall.
function bossPath(g,target){const cell=50,cols=44,rows=28;let points=new Map();for(let y=1;y<rows-1;y++)for(let x=1;x<cols-1;x++){let p={x:x*cell,y:y*cell};if(!blocked(p.x,p.y,g.r+2))points.set(y*cols+x,p)}let nearest=(p,visible)=>Array.from(points.entries()).filter(([,q])=>!visible||bodyLine(p,q,g.r+1)).sort((a,b)=>Math.hypot(a[1].x-p.x,a[1].y-p.y)-Math.hypot(b[1].x-p.x,b[1].y-p.y))[0]?.[0];let from=nearest(g,true),to=nearest(target,false);if(from===undefined||to===undefined)return [];let queue=[from],parents=new Map([[from,null]]);for(let at=0;at<queue.length;at++){let k=queue[at];if(k===to)break;for(let off of [-cols,cols,-1,1]){let n=k+off;if(!points.has(n)||parents.has(n)||!bodyLine(points.get(k),points.get(n),g.r+1))continue;parents.set(n,k);queue.push(n)}}if(!parents.has(to))return [];let path=[],k=to;while(k!==null){path.push(points.get(k));k=parents.get(k)}return path.reverse()}
tickBoss=function(g,dt){if(g.dead)return;g.flash=Math.max(0,g.flash-dt);g.spawnShield=Math.max(0,g.spawnShield-dt);if(g.spawnShield>0)return;let d=Math.hypot(player.x-g.x,player.y-g.y);g.timer-=dt;if(g.mode==='warn'){if(g.timer<=0){for(let i=0;i<12;i++){let a=i*Math.PI/6+elapsed*.2;shots.push({x:g.x,y:g.y,vx:Math.cos(a)*(simpleMode?150:195),vy:Math.sin(a)*(simpleMode?150:195),life:4})}effects.push({type:'boss',x:g.x,y:g.y,range:190,life:.7,max:.7,color:'#efa4ff'});if(d<190&&clearLine(g,player))hurt(simpleMode?1:2);g.mode='walk';g.timer=3.4;sfx('slam')}}else{let target=player;if(!bodyLine(g,player,g.r+1)){g.repath=(g.repath||0)-dt;if(g.repath<=0){g.path=bossPath(g,player);g.repath=.85}while(g.path?.length&&Math.hypot(g.path[0].x-g.x,g.path[0].y-g.y)<10)g.path.shift();target=g.path?.[0]||g}else g.path=[];let dx=target.x-g.x,dy=target.y-g.y,len=Math.hypot(dx,dy)||1,speed=(simpleMode?75:92)+Math.min(25,level);moveBody(g,dx/len*Math.min(len,speed*dt),dy/len*Math.min(len,speed*dt),g.r);if(g.timer<=0){g.mode='warn';g.timer=1.35;sfx('lure')}}if(d<g.r+17)hurt(simpleMode?1:2)};
const weaveUpdate=update;update=function(dt){if(state==='playing'){ghosts.forEach(g=>g.threadSlow=Math.max(0,(g.threadSlow||0)-dt));let ready=[];echoes=echoes.filter(e=>{e.delay-=dt;if(e.delay<=0){ready.push(e);return false}return true});ready.forEach(e=>{if(threads.includes(e.t))pulseThread(e.t,e.scale,true)});if(scene)return;shots.filter(b=>b.moth).forEach(b=>{if(!b.target||b.target.dead)b.target=mothTarget(b);if(b.target){let dx=b.target.x-b.x,dy=b.target.y-b.y,d=Math.hypot(dx,dy)||1,blend=Math.min(1,dt*8);b.vx+=(dx/d*400-b.vx)*blend;b.vy+=(dy/d*400-b.vy)*blend}})}weaveUpdate(dt)};
