update=function(dt){if(state==='levelup'){let t=levelTransition;if(!t){state='playing';return}t.elapsed+=dt;let fraction=Math.min(1,t.elapsed/t.duration);transitionAdvancing=true;state='playing';try{animatedUpdate(dt*Math.pow(1-fraction,2))}finally{transitionAdvancing=false;if(state==='playing')state='levelup'}if(t.elapsed>=t.duration&&state==='levelup'){levelTransition=null;state='playing';openUpgradeCards();arena.classList.remove('levelup-arriving');$('upgrade-panel').classList.add('cards-arriving')}return}animatedUpdate(dt)};
