function indicatorBounds(){let bounds={left:24,right:1076,top:82,bottom:625},rect=canvas.getBoundingClientRect?.();if(!rect||!rect.width||!rect.height)return bounds;let scale=Math.min(rect.width/1100,rect.height/660),ox=rect.left+(rect.width-1100*scale)/2,oy=rect.top+(rect.height-660*scale)/2;let top=arena.querySelector('.arena-top')?.getBoundingClientRect(),controls=arena.querySelector('.mobile')?.getBoundingClientRect();if(top)bounds.top=Math.max(bounds.top,(top.bottom-oy)/scale+16);if(controls&&controls.height>0&&controls.top<oy+660*scale)bounds.bottom=Math.min(bounds.bottom,(controls.top-oy)/scale-18);bounds.top=Math.min(190,bounds.top);bounds.bottom=Math.max(bounds.top+180,bounds.bottom);return bounds}
function houseIndicators(bounds=indicatorBounds()){let cx=player.x-camera.x,cy=player.y-camera.y;let dots=[];houses.forEach((h,id)=>{if(h.lit)return;let x=h.x-camera.x,y=h.y+20-camera.y;if(x>=0&&x<=1100&&y>=0&&y<=660)return;let dx=x-cx,dy=y-cy;if(!dx&&!dy)return;let bx=Math.max(bounds.left,Math.min(bounds.right,cx)),by=Math.max(bounds.top,Math.min(bounds.bottom,cy));let tx=dx>0?(bounds.right-bx)/dx:dx<0?(bounds.left-bx)/dx:Infinity,ty=dy>0?(bounds.bottom-by)/dy:dy<0?(bounds.top-by)/dy:Infinity,ratio=Math.max(0,Math.min(tx,ty));let edge=tx<ty?(dx>0?'right':'left'):(dy>0?'bottom':'top');dots.push({id,x:bx+dx*ratio,y:by+dy*ratio,edge})});for(let edge of ['top','bottom','left','right']){let horizontal=edge==='top'||edge==='bottom',axis=horizontal?'x':'y',lo=horizontal?bounds.left:bounds.top,hi=horizontal?bounds.right:bounds.bottom,list=dots.filter(d=>d.edge===edge).sort((a,b)=>a[axis]-b[axis]),gap=Math.min(22,(hi-lo)/Math.max(1,list.length));for(let i=1;i<list.length;i++)list[i][axis]=Math.max(list[i][axis],list[i-1][axis]+gap);if(list.length&&list.at(-1)[axis]>hi){list.at(-1)[axis]=hi;for(let i=list.length-2;i>=0;i--)list[i][axis]=Math.min(list[i][axis],list[i+1][axis]-gap)}}return dots}
const desktopMinimap=drawMinimap;
drawMinimap=function(){if(!mobileScene()){desktopMinimap();return}houseIndicators().forEach(d=>{glow(d.x,d.y,18,'#fff07455');ellipse(d.x,d.y,5,5,'#fff17a');ellipse(d.x-1,d.y-1,2,2,'#fffbd3')})};
