const bossArt={};
function loadBossArt(id,url){let asset=bossArt[id]={image:null,ready:false,crop:{x:0,y:0,w:512,h:512}};if(typeof Image==='undefined')return;let img=new Image();asset.image=img;img.onload=()=>{asset.ready=true;asset.crop={x:0,y:0,w:img.naturalWidth,h:img.naturalHeight};try{let c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;let cctx=c.getContext('2d');cctx.drawImage(img,0,0);let data=cctx.getImageData(0,0,c.width,c.height).data,minX=c.width,minY=c.height,maxX=0,maxY=0;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++)if(data[(y*c.width+x)*4+3]>30){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}if(maxX>minX&&maxY>minY)asset.crop={x:Math.max(0,minX-3),y:Math.max(0,minY-3),w:Math.min(c.width-minX+3,maxX-minX+7),h:Math.min(c.height-minY+3,maxY-minY+7)}}catch{}};img.onerror=()=>asset.ready=false;img.src=url}
