function paintBossArt(id,x,y,width,alpha=1,rotation=0){let a=bossArt[id];if(!a?.ready)return false;let c=a.crop,height=width*c.h/c.w;ctx.save();ctx.globalAlpha*=clamp01(alpha);ctx.translate(x,y);ctx.rotate(rotation);ctx.drawImage(a.image,c.x,c.y,c.w,c.h,-width/2,-height/2,width,height);ctx.restore();return true}
function paintSoul(x,y,size,alpha=1,rotation=0){if(paintBossArt('soul',x,y,size,alpha,rotation))return;ctx.save();ctx.globalAlpha*=clamp01(alpha);ellipse(x,y,size*.35,size*.45,'#d7bcf8');ellipse(x-size*.1,y,2,3,'#534573');ellipse(x+size*.1,y,2,3,'#534573');ctx.restore()}
