function paintKing(g,alpha=1,scale=1,sink=0,clock=elapsed){ctx.save();ctx.globalAlpha*=clamp01(alpha);ctx.translate(g.x,g.y+sink);ctx.scale(scale*(g.facing||1),scale);let bob=Math.sin(clock*2)*4;glow(0,bob,105,'#ca9fff28');if(g.flash>0){ctx.shadowColor='#fff4fd';ctx.shadowBlur=24}if(!paintBossArt('king',0,bob,g.r*3.05)){ctx.save();ctx.translate(-g.x,-g.y);ellipse(g.x,g.y,g.r,g.r,'#a783cf');for(let i=-1;i<=1;i++)ellipse(g.x+i*35,g.y+44,23,23,'#a783cf');ellipse(g.x-20,g.y-6,8,12,'#312443');ellipse(g.x+20,g.y-6,8,12,'#312443');star(g.x,g.y-66,23,'#ffe3a6');ctx.restore()}ctx.restore()}
function kingEntrance(g,t){let rise=easeScene(t/.34),gather=easeScene((t-.35)/.45),formed=easeScene((t-.68)/.24);ctx.save();ctx.globalAlpha=1-formed*.9;let gy=g.y+50+(1-rise)*75;if(!paintBossArt('grave',g.x,gy,145,rise)){ctx.fillStyle='#9383ac';ctx.globalAlpha=rise;ctx.beginPath();ctx.roundRect(g.x-36,gy-60,72,95,28);ctx.fill();star(g.x,gy-20,12,'#ffe5a7')}ctx.restore();for(let i=0;i<5;i++){let a=i*Math.PI*2/5+t*8,r=(65+Math.sin(t*3+i)*10)*(1-gather);paintSoul(g.x+Math.cos(a)*r,g.y-30+Math.sin(a)*r*.5+(1-rise)*60,30*(1-gather*.6),rise*(1-formed),a*.13)}if(formed>0)paintKing(g,formed,.65+.35*formed,0,t);if(t>.72)glow(g.x,g.y,160,'#dba5ff44')}
function kingDeath(g,t){let p=clamp01(t/.78);ctx.save();ctx.translate(Math.sin(t*45)*(1-p)*5,0);paintKing(g,1-p,1-p*.25,p*70,t);ctx.restore();for(let i=0;i<6;i++){let a=i*Math.PI/3;paintSoul(g.x+Math.cos(a)*(22+p*80),g.y-10-p*(70+i*10),23+p*9,Math.sin(p*Math.PI),a*.1)}glow(g.x,g.y+45,75*(1-p)+15,'#d8b5ff33')}
const bossDefinitions={ghostKing:{name:'유령의 왕',throughWalls:true,introDuration:2,deathDuration:1.7,intro:kingEntrance,death:kingDeath}};
function bossDefinition(n=level){let planned=bossCycle[Math.floor((n-10)/10+4000)%4];return {planned,id:bossDefinitions[planned]?planned:'ghostKing',definition:bossDefinitions[planned]||bossDefinitions.ghostKing}}
function followCamera(p=player){return {x:Math.max(0,Math.min(WORLD.w-1100,p.x-550)),y:Math.max(0,Math.min(WORLD.h-660,p.y-330))}}
function beginScene(kind,duration,actor=null){if(scene)return false;levelTransition=null;arena.classList.remove('levelup-arriving');keys={};releaseStick();dash=0;scene={kind,duration,t:0,actor,from:{...camera},impact:false,alive:ghosts.filter(g=>!g.dead&&g.type!=='boss')};state='cinematic';return true}
function presentationSound(kind){if(muted)return;sfx(kind==='intro'?'nova':'wave');if(kind==='intro'){beep(196,.25)}else if(kind==='victory'){beep(1047,.3)}}
function sceneShake(){if(!scene)return 0;let at=scene.kind==='boss-intro'?.88:scene.kind==='boss-death'?.78:10;return Math.max(0,1-Math.abs(sceneTime()-at)/.13)*5}
