// Only this boss bypasses internal stones. World bounds remain solid.
tickBoss=function(g,dt){if(g.dead||scene)return;g.flash=Math.max(0,g.flash-dt);g.spawnShield=Math.max(0,g.spawnShield-dt);if(g.spawnShield>0)return;let dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;g.timer-=dt;if(g.mode==='warn'){if(g.timer<=0){for(let i=0;i<12;i++){let a=i*Math.PI/6+elapsed*.2;shots.push({x:g.x,y:g.y,vx:Math.cos(a)*(simpleMode?150:195),vy:Math.sin(a)*(simpleMode?150:195),life:4})}effects.push({type:'boss',x:g.x,y:g.y,range:190,life:.7,max:.7,color:'#efa4ff'});if(d<190&&clearLine(g,player))hurt(simpleMode?1:2);g.mode='walk';g.timer=3.4;sfx('slam')}}else{let speed=(simpleMode?75:92)+Math.min(25,level),step=Math.min(d,speed*dt);if(bossDefinitions[g.bossId||'ghostKing'].throughWalls){g.x=Math.max(30+g.r,Math.min(WORLD.w-30-g.r,g.x+dx/d*step));g.y=Math.max(30+g.r,Math.min(WORLD.h-30-g.r,g.y+dy/d*step))}else moveBody(g,dx/d*step,dy/d*step,g.r);if(g.timer<=0){g.mode='warn';g.timer=1.35;sfx('lure')}}if(d<g.r+17)hurt(simpleMode?1:2)};
drawBoss=function(g){paintKing(g);text('유령의 왕',g.x,g.y-110,16,'#f1d6ff');if(blocked(g.x,g.y,g.r)){ctx.save();ctx.strokeStyle='#e1baff';ctx.lineWidth=2;ctx.setLineDash([5,5]);ctx.beginPath();ctx.arc(g.x,g.y,g.r+9,0,Math.PI*2);ctx.stroke();ctx.restore()}if(g.mode==='warn'){ellipse(g.x,g.y,190,190,'#ff86c52a');ctx.strokeStyle='#ffb4e5';ctx.lineWidth=4;ctx.beginPath();ctx.arc(g.x,g.y,190,0,Math.PI*2);ctx.stroke();text('충격파 준비!',g.x,g.y+95,18,'#fff1b8')}};
const ordinaryEnemyDraw=drawEnemy;
drawEnemy=function(g,i){if(scene?.actor===g){let def=bossDefinitions[g.bossId||'ghostKing'];if(scene.kind==='boss-intro')def.intro(g,Math.max(0,sceneTime()-.15));else if(scene.kind==='boss-death')def.death(g,sceneTime());return}if(g.dead)return;let melting=scene&&['night-clear','boss-death'].includes(scene.kind),p=melting?clamp01(scene.t/(scene.kind==='night-clear'?.5:.65)):0;let rise=scene?.kind==='night-rise'?easeScene(scene.t/.45):g.birth>0?easeScene(1-g.birth/.4):1;ctx.save();ctx.translate(g.x,g.y+g.r);ctx.scale(1+Math.sin(p*12+i)*p*.2,Math.max(.03,(1-p)*rise));ctx.translate(-g.x,-g.y-g.r);ctx.globalAlpha=(1-p)*rise;ordinaryEnemyDraw(g,i);ctx.restore()};
function drawSceneWorld(){if(!scene)return;let s=scene;if(s.kind==='night-clear'||s.kind==='boss-death'){let p=clamp01(s.t/s.duration);houses.filter(h=>h.lit).forEach(h=>{glow(h.x,h.y,80+p*240,'#ffe7a544');ctx.save();ctx.globalAlpha=Math.sin(p*Math.PI);for(let i=0;i<8;i++){let a=i*Math.PI/4;star(h.x+Math.cos(a)*p*150,h.y+Math.sin(a)*p*90,5,'#ffe9ac')}ctx.restore()});if(s.kind==='boss-death'){glow(s.actor.x,s.actor.y,100+p*250,'#e5c4ff44');for(let i=0;i<14;i++){let a=i*Math.PI/7;star(s.actor.x+Math.cos(a)*p*230,s.actor.y+Math.sin(a)*p*150,5*(1-p),'#ffe9ac')}}}}
