// Scene time stays normalized to the original choreography; each boss owns its duration.
function sceneTime(){if(!scene)return 0;return scene.t*(scene.kind==='boss-intro'?1.35:scene.kind==='boss-death'?.85:scene.duration)/scene.duration}
loadBossArt('dracula','assets/dracula.png');loadBossArt('coffinClosed','assets/coffin_closed.png');loadBossArt('coffinOpen','assets/coffin_open.png');loadBossArt('bat','assets/bat.png');
function faceBoss(g){if(!g.facing)g.facing=1;if(['walk','rest','recover'].includes(g.mode)&&Math.abs(player.x-g.x)>18)g.facing=player.x>g.x?1:-1}
function batPicture(x,y,size,alpha=1,rotation=0,facing=1){ctx.save();ctx.translate(x,y);ctx.scale(facing,1);if(!paintBossArt('bat',0,0,size,alpha,rotation)){ctx.globalAlpha*=alpha;ellipse(0,0,size*.17,size*.2,'#625076');ellipse(-size*.28,-3,size*.26,size*.1,'#a45179');ellipse(size*.28,-3,size*.26,size*.1,'#a45179');ellipse(-3,0,1.5,2,'#ffb4c8');ellipse(3,0,1.5,2,'#ffb4c8')}ctx.restore()}
function paintDracula(g,alpha=1,scale=1,dx=0,dy=0,tilt=0,clock=elapsed){ctx.save();ctx.translate(g.x+dx,g.y+dy);ctx.scale((g.facing||1)*scale,scale);ctx.rotate(tilt);ctx.globalAlpha*=clamp01(alpha);glow(0,0,90,'#e54b6b24');if(g.flash>0){ctx.shadowColor='#fff2ef';ctx.shadowBlur=25}if(!paintBossArt('dracula',0,Math.sin(clock*3)*3,g.r*3)){ctx.fillStyle='#462b4b';ctx.beginPath();ctx.moveTo(-65,45);ctx.lineTo(0,-35);ctx.lineTo(65,45);ctx.closePath();ctx.fill();ellipse(0,-12,32,35,'#eadde7');ellipse(-11,-13,4,5,'#c13764');ellipse(11,-13,4,5,'#c13764');star(0,30,9,'#ef797b')}ctx.restore()}
// Both coffin states share one ground anchor and visible height, independent of PNG margins.
function coffinPicture(id,x,ground,height,alpha){let a=bossArt[id];if(a?.ready){let c=a.crop;return paintBossArt(id,x,ground-height/2,height*c.w/c.h,alpha)}ctx.save();ctx.globalAlpha*=alpha;ctx.fillStyle=id==='coffinOpen'?'#7c294b':'#4c3046';ctx.beginPath();ctx.roundRect(x-36,ground-height,72,height,18);ctx.fill();star(x,ground-height*.55,13,'#ec9b91');ctx.restore()}
function draculaEntrance(g,t){let rise=easeScene(t/.38),open=easeScene((t-.35)/.18),reveal=easeScene((t-.58)/.32);glow(g.x,g.y+48,60+rise*70,'#d72c7144');let ground=g.y+72+(1-rise)*85;coffinPicture('coffinClosed',g.x,ground,150,rise*(1-open));coffinPicture('coffinOpen',g.x,ground,150,rise*open*(1-reveal*.85));for(let i=0;i<6;i++){let a=i*Math.PI/3+t*3;glow(g.x+Math.cos(a)*35,g.y+25-i*10,24,'#df416c33');if(t>.4)batPicture(g.x+Math.cos(a)*(20+reveal*70),g.y-25+Math.sin(a)*35-reveal*35,24,open*(1-reveal*.7),Math.sin(a)*.25)}if(reveal>0)paintDracula(g,reveal,.7+.3*reveal,0,(1-reveal)*45,0,t)}
function draculaDeath(g,t){let p=clamp01(t/.85),lift=easeScene((p-.38)/.62),swarm=easeScene(p/.4);let dx=lift*210,dy=-lift*850;paintDracula(g,1-lift*.25,1-lift*.25,dx,dy,Math.sin(t*18)*.12+lift*.5,t);for(let i=0;i<7;i++){let a=i*Math.PI*2/7+t*7,r=100-(swarm*65);batPicture(g.x+dx+Math.cos(a)*r,g.y+dy+Math.sin(a)*r*.6-15,30,Math.min(1,p*6),Math.sin(a)*.2,i%2?1:-1)}}
