enemyTypes.bat={name:'꼬마 박쥐',color:'#c784ac',hp:2,speed:1,r:11};
function bossAim(g){let dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;return {x:dx/d,y:dy/d}}
function beamEnd(g,aim,length=720){let end={x:g.x,y:g.y};for(let distance=8;distance<=length;distance+=8){let x=g.x+aim.x*distance,y=g.y+aim.y*distance;if(blocked(x,y,1))break;end={x,y}}return end}
function chargeEnd(g){let length=(simpleMode?520:610)*.52,end={x:g.x,y:g.y};for(let distance=4;distance<length+4;distance+=4){let span=Math.min(length,distance),x=g.x+g.aim.x*span,y=g.y+g.aim.y*span;if(blocked(x,y,g.r))break;end={x,y}}return end}
function recoverDracula(g){g.mode='recover';g.timer=simpleMode?1.15:.9;g.beam=null}
function planDracula(g){let pattern=['charge','laser','summon'][g.patternIndex++%3];g.aim=bossAim(g);g.facing=Math.abs(g.aim.x)>.08?Math.sign(g.aim.x):g.facing;g.mode=pattern+'Warn';g.timer=pattern==='charge'?.95:pattern==='laser'?1.15:.9;g.beam=pattern==='laser'?beamEnd(g,g.aim):null;sfx('lure')}
function summonBats(g){let count=ghosts.filter(v=>v.type==='bat'&&!v.dead).length;for(let i=0;i<4-count;i++){let angle=i*Math.PI/2,p=null;for(let step=0;step<12;step++){let a=angle+step*.5,q={x:g.x+Math.cos(a)*95,y:g.y+Math.sin(a)*95};if(!blocked(q.x,q.y,13)&&Math.hypot(q.x-player.x,q.y-player.y)>65){p=q;break}}if(!p)continue;ghosts.push({...p,type:'bat',owner:g,hp:2,maxHp:2,r:11,dead:false,flash:0,stun:0,mode:'walk',birth:.4,ttl:10,repath:0,path:[],facing:1,fire:99})}sfx('lure')}
function tickBat(g,dt){if(g.dead)return;g.ttl-=dt;if(g.ttl<=0||g.owner.dead){g.dead=true;g.respawn=Infinity;return}g.flash=Math.max(0,g.flash-dt);if(g.birth>0){g.birth=Math.max(0,g.birth-dt);return}if(g.stun>0){g.stun=Math.max(0,g.stun-dt);return}let target=player;if(!bodyLine(g,player,g.r+1)){g.repath-=dt;if(g.repath<=0){g.path=bossPath(g,player);g.repath=.8}while(g.path.length&&Math.hypot(g.path[0].x-g.x,g.path[0].y-g.y)<8)g.path.shift();target=g.path[0]||g}else g.path=[];let dx=target.x-g.x,dy=target.y-g.y,d=Math.hypot(dx,dy)||1,speed=(225+rank('stride')*18)*1.13*(g.threadSlow>0?.55:1);if(Math.abs(dx)>4)g.facing=Math.sign(dx);moveBody(g,dx/d*Math.min(d,speed*dt),dy/d*Math.min(d,speed*dt),g.r);if(Math.hypot(g.x-player.x,g.y-player.y)<g.r+14)hurt(1)}
function tickDracula(g,dt){g.flash=Math.max(0,g.flash-dt);g.timer-=dt;let dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;if(g.mode==='walk'){let target=player;if(!bodyLine(g,player,g.r+1)){g.repath=(g.repath||0)-dt;if(g.repath<=0){g.path=bossPath(g,player);g.repath=.8}while(g.path?.length&&Math.hypot(g.path[0].x-g.x,g.path[0].y-g.y)<10)g.path.shift();target=g.path?.[0]||g}let mx=target.x-g.x,my=target.y-g.y,md=Math.hypot(mx,my)||1,speed=simpleMode?85:102;moveBody(g,mx/md*Math.min(md,speed*dt),my/md*Math.min(md,speed*dt),g.r);if(g.timer<=0)planDracula(g)}else if(g.mode==='chargeWarn'&&g.timer<=0){g.mode='charge';g.timer=.52;sfx('dash')}else if(g.mode==='charge'){let step=(simpleMode?520:610)*Math.min(dt,Math.max(0,g.timer+dt));let hit=moveBody(g,g.aim.x*step,g.aim.y*step,g.r);if(hit||g.timer<=0){recoverDracula(g);if(hit)sfx('wall')}}else if(g.mode==='laserWarn'&&g.timer<=0){g.mode='laser';g.timer=.48;sfx('nova')}else if(g.mode==='laser'){let p=projection(player,g,g.beam);if(Math.hypot(player.x-p.x,player.y-p.y)<18+17&&clearLine(g,player))hurt(simpleMode?1:2);if(g.timer<=0)recoverDracula(g)}else if(g.mode==='summonWarn'&&g.timer<=0){summonBats(g);recoverDracula(g)}else if(g.mode==='recover'&&g.timer<=0){g.mode='walk';g.timer=Math.max(1.3,2.3-(level-20)*.012)+(simpleMode?.4:0)}if(d<g.r+17)hurt(g.mode==='charge'&&!simpleMode?2:1)}
const kingCombat=tickBoss;tickBoss=function(g,dt){if(g.dead||scene)return;faceBoss(g);if(g.bossId==='dracula')tickDracula(g,dt);else kingCombat(g,dt)};
const kingRender=drawBoss;drawBoss=function(g){if(g.bossId!=='dracula'){kingRender(g);return}let tilt=g.mode==='chargeWarn'?-.08:g.mode==='charge'?.12:0;paintDracula(g,1,1,0,0,tilt);text('드라큘라',g.x,g.y-110,16,'#ffc1d3');ctx.save();if(g.mode==='chargeWarn'){let end=chargeEnd(g);line(g.x,g.y,end.x,end.y,'#ff849f35',g.r*2);line(g.x,g.y,end.x,end.y,'#ffb2be',3);text('돌진!',g.x,g.y-85,15,'#ffb1c2')}if(g.mode==='laserWarn'||g.mode==='laser'){let firing=g.mode==='laser';ctx.lineCap='round';line(g.x,g.y,g.beam.x,g.beam.y,firing?'#ff356b99':'#ff527442',36);line(g.x,g.y,g.beam.x,g.beam.y,firing?'#fff0dc':'#ffb5ba',firing?8:2);if(firing){ctx.shadowColor='#ff3c6e';ctx.shadowBlur=24;line(g.x,g.y,g.beam.x,g.beam.y,'#ff7292',17)}else text('빛을 피해!',g.x,g.y-85,15,'#ffb1c2')}if(g.mode==='summonWarn'){glow(g.x,g.y,110,'#c86caa44');for(let i=0;i<4;i++){let a=i*Math.PI/2+elapsed;batPicture(g.x+Math.cos(a)*80,g.y+Math.sin(a)*40,22,.5)}text('박쥐가 모여든다!',g.x,g.y-85,15,'#e5b1ee')}ctx.restore()};
const bossAndEnemyRender=drawEnemy;drawEnemy=function(g,i){if(g.type!=='bat'){bossAndEnemyRender(g,i);return}if(g.dead)return;let appear=g.birth>0?clamp01(1-g.birth/.4):1,fade=Math.min(1,g.ttl);ctx.save();if(g.flash>0){ctx.shadowColor='#fff';ctx.shadowBlur=16}batPicture(g.x,g.y+Math.sin(elapsed*15+i)*3,36+Math.sin(elapsed*23+i)*3,appear*fade,Math.sin(elapsed*12+i)*.07,g.facing);ctx.restore()};
const sceneAudio=presentationSound;presentationSound=function(kind){if(scene?.actor?.bossId==='dracula'&&kind==='intro'){sfx('slam');beep(146,.3);return}sceneAudio(kind)};
const batCleanupUpdate=update;update=function(dt){batCleanupUpdate(dt);if(state==='playing')ghosts=ghosts.filter(g=>g.type!=='bat'||!g.dead)};

