function paintMoon(g,{flight=false,height=0,alpha=1,scale=1,tilt=0}={}){
 ctx.save();ctx.globalAlpha*=clamp01(alpha);ellipse(g.x,g.y+40,Math.max(14,45-height*.12),12,'#162a3e55');ctx.translate(g.x,g.y-height);ctx.scale(-(g.facing||1)*scale,scale);ctx.rotate(tilt);
 if(g.flash>0){ctx.shadowColor='#fff';ctx.shadowBlur=24}
 if(!paintBossArt(flight?'moonFlight':'moonRabbit',0,0,125)){ellipse(0,0,43,48,'#d7e5fa');ellipse(-16,-57,10,30,'#fff1e3');ellipse(12,-57,10,30,'#fff1e3');ellipse(0,-8,32,33,'#fff1e3');ellipse(-12,-10,4,6,'#493951');ellipse(10,-10,4,6,'#493951');ellipse(-31,21,21,14,'#a5e3d6');star(-40,21,8,'#f4a2d5')}
 if(flight){glow(20,63,32,'#a8dfff55');star(20,72,11+Math.sin(elapsed*24)*3,'#d2eeff')}ctx.restore();
}
function moonEntrance(g,t){let land=easeScene(t/.46),exit=easeScene((t-.48)/.31);let sy=g.y+12-(1-land)*330;
 if(!paintBossArt('moonShip',g.x,sy,185,1-exit*.8)){ellipse(g.x,sy,90,35,'#d2dcf0');ellipse(g.x,sy-24,43,32,'#544665')}
 if(t>.4){glow(g.x,g.y+65,90,'#ffe7b744');for(let i=0;i<7;i++){let a=i*Math.PI/3.5;star(g.x+Math.cos(a)*land*95,g.y+50+Math.sin(a)*18,4,'#ffe4bc')}}
 if(exit>0){ellipse(g.x,g.y+24,22,30,'#d6d1ff66');paintMoon({...g,x:g.x-(1-exit)*35},{alpha:exit,scale:.8+.2*exit})}
}
function moonDeath(g,t){let p=clamp01(t/.85),launch=easeScene((p-.35)/.65);paintMoon(g,{flight:p>.35,height:launch*950,scale:1-launch*.3,tilt:Math.sin(p*30)*(1-launch)*.12});if(p<.45){star(g.x+25,g.y+20,8,'#ff8fbf');text('앗! 귀환!',g.x,g.y-110,17,'#fff1d2')}for(let i=0;i<9;i++)star(g.x+Math.sin(i*3+p*10)*25,g.y+50-launch*600+i*12,4*(1-launch),'#bceaff')}
bossDefinitions.moonRabbit={name:'달에서 온 토끼',throughWalls:false,introDuration:2.1,deathDuration:1.8,intro:moonEntrance,death:moonDeath};
const moonSpawnBase=spawnBoss;spawnBoss=function(){moonSpawnBase();let g=scene?.actor;if(g?.bossId==='moonRabbit'){g.hp=g.maxHp=Math.round(g.maxHp*.68);g.airborne=false;g.height=0;g.mark=null;g.volley=0;g.patternIndex=0}};
const moonHitBase=hitGhost;hitGhost=function(g,...args){if(g.airborne&&!g.dead&&g.hp>0)return;return moonHitBase(g,...args)};
function moonRecover(g,landing=false){g.mode='recover';g.timer=landing?2.1:1.15;g.airborne=false;g.height=0;g.mark=null}
function moonPlan(g){let pattern=['line','fan','ring','flight'][g.patternIndex++%4];g.pattern=pattern;g.mode='moonWarn';g.timer=pattern==='flight'?.65:.7;g.aim=bossAim(g);if(Math.abs(g.aim.x)>.08)g.facing=Math.sign(g.aim.x)}
function moonShot(g,a,speed){if(shots.filter(b=>b.moon&&!b.friendly).length>=36)return;let x=g.x+Math.cos(a)*(g.r+9),y=g.y+Math.sin(a)*(g.r+9);if(!clearLine(g,{x,y}))return;shots.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:4.2,moon:true})}
function moonVolley(g){let a=Math.atan2(g.aim.y,g.aim.x),speed=simpleMode?175:215;if(g.pattern==='line'){moonShot(g,a,speed+45)}else if(g.pattern==='fan'){for(let i=-3;i<=3;i++)moonShot(g,a+i*.29,speed)}else{for(let i=0;i<12;i++)moonShot(g,a+.18+i*Math.PI/6,speed-20)}sfx('shot')}
// One fixed impact at a time, and only if a reachable safe point exists nearby.
function moonMark(g){let mark={x:player.x+Math.sin(g.airCount*Math.PI/2)*26,y:player.y,r:54,phase:'warn',timer:simpleMode?1:.85};let safe=false;for(let i=0;i<16;i++){let a=i*Math.PI/8,p={x:mark.x+Math.cos(a)*105,y:mark.y+Math.sin(a)*105};if(!blocked(p.x,p.y,18)&&bodyLine(player,p,18)){safe=true;break}}g.mark=safe?mark:null;g.timer=mark?mark.timer:.3;g.mode='airWarn'}
function tickMoon(g,dt){if(g.dead||scene)return;g.flash=Math.max(0,g.flash-dt);g.timer-=dt;
 if(g.mode==='walk'){faceBoss(g);let target=player;if(!bodyLine(g,player,g.r+1)){g.repath=(g.repath||0)-dt;if(g.repath<=0){g.path=bossPath(g,player);g.repath=.8}while(g.path?.length&&Math.hypot(g.path[0].x-g.x,g.path[0].y-g.y)<10)g.path.shift();target=g.path?.[0]||g}let dx=target.x-g.x,dy=target.y-g.y,d=Math.hypot(dx,dy)||1;if(Math.hypot(player.x-g.x,player.y-g.y)>260)moveBody(g,dx/d*Math.min(d,75*dt),dy/d*Math.min(d,75*dt),g.r);if(g.timer<=0)moonPlan(g)}
 else if(g.mode==='moonWarn'&&g.timer<=0){if(g.pattern==='flight'){g.airborne=true;g.mode='rising';g.timer=.4;g.airCount=0;shots=shots.filter(b=>!b.moon||b.friendly);sfx('dash')}else{moonVolley(g);g.volley=1;if(g.pattern==='line'){g.mode='burst';g.timer=.2}else moonRecover(g)}}
 else if(g.mode==='burst'&&g.timer<=0){moonVolley(g);g.volley++;g.timer=.2;if(g.volley>=5)moonRecover(g)}
 else if(g.mode==='recover'&&g.timer<=0){g.mode='walk';g.timer=1.2}
 else if(g.mode==='rising'){g.height=125*easeScene(1-g.timer/.4);if(g.timer<=0){g.height=125;moonMark(g)}}
 else if(g.mode==='airWarn'){if(g.mark)g.mark.timer=Math.max(0,g.timer);if(g.timer<=0){g.mode='airStrike';g.timer=.18;if(g.mark){g.mark.phase='strike';let m=g.mark;if(Math.hypot(player.x-m.x,player.y-m.y)<m.r+14)hurt(1);sfx('slam')}}}
 else if(g.mode==='airStrike'&&g.timer<=0){g.mark=null;if(++g.airCount>=3){g.mode='landing';g.timer=.35}else moonMark(g)}
 else if(g.mode==='landing'){g.height=125*(1-easeScene(1-g.timer/.35));if(g.timer<=0){moonRecover(g,true);burst(g.x,g.y+35,'#d3eaff',12);sfx('wall')}}
 if(!g.airborne&&Math.hypot(g.x-player.x,g.y-player.y)<g.r+17)hurt(1);
}
const moonTickBase=tickBoss;tickBoss=function(g,dt){if(g.bossId==='moonRabbit')tickMoon(g,dt);else moonTickBase(g,dt)};
const moonDrawBase=drawBoss;drawBoss=function(g){if(g.bossId!=='moonRabbit'){moonDrawBase(g);return}paintMoon(g,{flight:g.airborne,height:g.height||0,scale:g.airborne?.92:1});text('달에서 온 토끼',g.x,g.y-(g.height||0)-108,15,'#f6d5ff');if(g.airborne)text('공중 · 착륙을 기다려!',g.x,g.y+76,13,'#e6d8ff');if(g.mode==='moonWarn'){text(g.pattern==='flight'?'비행 준비!':g.pattern==='ring'?'별빛 확산!':g.pattern==='fan'?'부채 사격!':'연속 사격!',g.x,g.y+88,15,'#ffc9e7');if(g.pattern!=='flight'){let a=Math.atan2(g.aim.y,g.aim.x);line(g.x,g.y,g.x+Math.cos(a)*260,g.y+Math.sin(a)*260,'#ffc1e588',2)}}if(g.mark){let m=g.mark;ctx.save();ellipse(m.x,m.y,m.r,m.r,m.phase==='warn'?'#ff9ade33':'#ffd6ff99');ctx.strokeStyle='#ffb8ee';ctx.lineWidth=3;ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,Math.PI*2);ctx.stroke();if(m.phase==='strike'){line(m.x,m.y-450,m.x,m.y,'#e3a1ff77',m.r*1.25);line(m.x,m.y-450,m.x,m.y,'#fff1ff',12);glow(m.x,m.y,m.r+20,'#ffaeef88')}else{star(m.x,m.y,6,'#ffd4f4');ctx.beginPath();ctx.arc(m.x,m.y,m.r*(.3+.7*(m.timer/(simpleMode?MOON_FLIGHT.easyWarn:MOON_FLIGHT.warn))),0,Math.PI*2);ctx.stroke()}ctx.restore()}};
function paintMoonBullet(b){glow(b.x,b.y,17,b.friendly?'#bfffff44':'#ff9cdd44');if(!paintBossArt('moonBullet',b.x,b.y,23)){ellipse(b.x,b.y,7,7,'#ffd4f2')}if(b.friendly)star(b.x,b.y,5,'#bbfff1')}
const moonDefeatBase=beginBossDefeat;beginBossDefeat=function(g){g.airborne=false;g.height=0;g.mark=null;moonDefeatBase(g)};
