showStory=function(){state='story';document.body.classList.add('playing-view');$('overlay').classList.add('hidden');
 const pages=[
 ['달 아래, 잠 못 드는 마을','유령이 드리운 지구의 동물 마을.<br>밤톨과 루루, 포포와 솜이, 달곰은<br>별빛 없는 밤이면 잠들지 못했어.'],
 ['달에서 온 작은 배달부','달에서 그 모습을 지켜보던 모찌는<br>작은 별주머니를 메고 내려왔어.<br>“내가 너희의 밤을 밝혀 줄게.”'],
 ['오늘 밤도, 별을 배달해','별 세 개를 모아 친구의 집에 전해 줘.<br>집과 집에 이어진 실을 대시로 가르면<br>유령을 물리칠 달빛이 피어나.<br>모찌와 함께, 오늘 밤도 포근하게.']];let chapter=0;
 function launch(){start();arena.classList.add('story-launch')}
 function page(){openJournal(pages[chapter][0]);let journal=$('journal');journal.classList.add('story-reading');journal.setAttribute('data-chapter',String(chapter+1));$('journal-body').innerHTML='<div class="story-page"><div class="storybook-scene" aria-hidden="true"><span class="storybook-moon">☾</span><span class="storybook-star star-one">✦</span><span class="storybook-star star-two">✧</span><span class="storybook-star star-three">✦</span><span class="storybook-rabbit">🐇<b>✦</b></span><div class="storybook-village"><i>⌂</i><i>⌂</i><i>⌂</i></div></div><p class="storybook-prose">'+pages[chapter][1]+'</p><div class="story-meta" aria-label="이야기 '+(chapter+1)+'장, 총 3장"><span class="story-dots" aria-hidden="true">'+[0,1,2].map(n=>'<i class="'+(n===chapter?'current':'')+'"></i>').join('')+'</span>'+(chapter+1)+' / 3</div>'+(chapter===2?'<small class="story-controls">이동 · 별 줍기 · 집 앞에서 E 또는 배달 버튼<br>대시로 빛의 실을 가로질러 봐.</small>':'')+'<button id="story-next" class="primary">'+(chapter===2?'별을 주우러 가자 →':'다음 이야기 →')+'</button></div>';$('story-next').onclick=()=>{if(chapter===2)launch();else{chapter++;page()}};$('journal-close').textContent='이야기 건너뛰고 시작';$('journal-close').onclick=launch;let heading=$('journal-title');heading.style.animation='none';void heading.offsetWidth;heading.style.animation='';$('story-next').focus()}
 page();
};

const TURTLE_REST={enter:.3,rest:1.8,leave:.3,fraction:.15};
function beginTurtleRest(g){g.mode='heal';g.healElapsed=0;g.healRecovered=0;g.timer=TURTLE_REST.enter+TURTLE_REST.rest+TURTLE_REST.leave;sfx('lure')}
function advanceTurtleRest(g,dt){if(g.dead||g.hp<=0)return;let cfg=TURTLE_REST,total=cfg.enter+cfg.rest+cfg.leave,previous=g.healElapsed||0;g.healElapsed=Math.min(total,previous+Math.max(0,dt));let before=clamp01((previous-cfg.enter)/cfg.rest),after=clamp01((g.healElapsed-cfg.enter)/cfg.rest),gain=g.maxHp*cfg.fraction*(after-before),hp=g.hp;g.hp=Math.min(g.maxHp,g.hp+gain);g.healRecovered+=g.hp-hp;g.hpTrail=Math.max(g.hpTrail||g.hp,g.hp);g.timer=Math.max(0,total-g.healElapsed);if(g.healElapsed>=total){burst(g.x,g.y,'#d9efb4',12);floaters.push({x:g.x,y:g.y-70,label:'+ '+Math.round(g.healRecovered),color:'#bcecc5',life:.65});sfx('choose');g.mode='recover';g.timer=.45}}
const restPaintBase=paintTurtle;paintTurtle=function(g,options={}){if(g.mode!=='heal'||options.form!=='turtleShell'){restPaintBase(g,options);return}let t=g.healElapsed||0,c=TURTLE_REST,total=c.enter+c.rest+c.leave,mix=Math.min(easeScene(t/c.enter),easeScene((total-t)/c.leave)),breath=1+Math.sin(Math.max(0,t-c.enter)*Math.PI*2/1.6)*.018*mix;restPaintBase(g,{...options,form:'turtle',alpha:(options.alpha??1)*(1-mix)});restPaintBase(g,{...options,form:'turtleShell',alpha:(options.alpha??1)*mix,scale:(options.scale??1)*breath});ctx.save();ctx.globalAlpha=mix;glow(g.x,g.y+20,82,'#d1e9a522');for(let i=0;i<7;i++){let p=(Math.max(0,t-c.enter)*.45+i/7)%1,x=g.x+Math.sin(i*2.4)*72+Math.sin(t*2+i)*5,y=g.y+40-p*115;ctx.save();ctx.globalAlpha=Math.sin(p*Math.PI)*.65;star(x,y,2.4+i%2,i%2?'#f3eab0':'#c9edb3');ctx.restore()}ctx.restore()};

showTitle();

function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);tickMusic();draw();requestAnimationFrame(frame)}for(let i=0;i<16;i++)spawnStar();requestAnimationFrame(frame);
